bash.command:
# M1: scaffold frozen four-package workspace, health and CLI
node --input-type=module <<'JS'
import { readFileSync } from "node:fs";
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  let r;
  console.log((await lf.branch.fork("implementation")).kind);
  r = await lf.fs.apply("implementation", JSON.parse(readFileSync("{{scenario}}/changes/001.json", "utf8")), "M1 scaffold frozen four-package workspace, health and CLI");
  console.log(JSON.stringify({ kind: r.kind, head: r.head }));
} finally {
  await lf.close();
}
JS

# M1: fetch
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
let sandbox, ws;
try {
  let r;
  ({ sandbox } = await lf.sandbox.create());
  ws = await lf.workspace.mount(sandbox, "implementation");
  await lf.workspace.exec(ws, "CARGO_HOME=$PWD/.cargo-home timeout 110 cargo fetch --locked", "fetch", { stdout: process.stdout, stderr: process.stderr });
  r = await lf.workspace.commit(ws, "M1 fetch (exit 0)");
  console.log(JSON.stringify({ kind: r.kind, head: r.head }));
} finally {
  if (ws) await lf.workspace.unmount(ws);
  if (sandbox) await lf.sandbox.close(sandbox);
  await lf.close();
}
