node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
let sandbox, ws;
try {
  let r;
  ({ sandbox } = await lf.sandbox.create());
  ws = await lf.workspace.mount(sandbox, "combined");
  await lf.workspace.exec(ws, "timeout 110 python3 tests/full.py large-v1 candidate", "M6 candidate large-v1", { stdout: process.stdout, stderr: process.stderr });
  r = await lf.workspace.commit(ws, "M6 candidate large-v1 (exit 0)");
  console.log(JSON.stringify({ kind: r.kind, head: r.head }));
} finally {
  if (ws) await lf.workspace.unmount(ws);
  if (sandbox) await lf.sandbox.close(sandbox);
  await lf.close();
}
