const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
let sandbox, ws;
try {
  let r;
  ({ sandbox } = await lf.sandbox.create());
  ws = await lf.workspace.mount(sandbox, "final-main-acceptance");
  await lf.workspace.exec(ws, "timeout 110 bash -c 'set -e; CARGO_HOME=$PWD/.cargo-home timeout 30 cargo package --list --locked --allow-dirty -p depot-domain; CARGO_HOME=$PWD/.cargo-home timeout 30 cargo package --list --locked --allow-dirty -p depot-store; CARGO_HOME=$PWD/.cargo-home timeout 30 cargo package --list --locked --allow-dirty -p depot-server; CARGO_HOME=$PWD/.cargo-home timeout 30 cargo package --list --locked --allow-dirty -p depot-cli'", "final-main package-listings", { stdout: process.stdout, stderr: process.stderr });
  r = await lf.workspace.commit(ws, "final-main acceptance package-listings (exit 0)");
  console.log(JSON.stringify({ kind: r.kind, head: r.head }));
} finally {
  if (ws) await lf.workspace.unmount(ws);
  if (sandbox) await lf.sandbox.close(sandbox);
  await lf.close();
}
